 void parameter(Param param,Object value,Models.Context context){if(param.type.equals("b")){monitor.edit(param,!b(value),value,context);return;}if(param.type.equals("i")&&param.max-param.min<=512){String[] options=new String[(int)(param.max-param.min+1)];for(int i=0;i<options.length;i++)options[i]=param.display((int)param.min+i);new AlertDialog.Builder(this).setTitle(param.name).setSingleChoiceItems(options,(int)(d(value)-param.min),(dialog,index)->{monitor.edit(param,(int)param.min+index,value,context);dialog.dismiss();}).setNegativeButton("Cancel",null).show();return;}EditText field=new EditText(this);field.setInputType(8194|4096);field.setText(String.valueOf(d(value)));new AlertDialog.Builder(this).setTitle(param.name+" ("+param.min+"…"+param.max+")").setView(field).setNegativeButton("Cancel",null).setPositiveButton("Apply",(dialog,w)->{try{double v=Double.parseDouble(field.getText().toString());param.valid(v);monitor.edit(param,v,value,context);}catch(Exception e){problem("Enter a value within the supported range.");}}).show();}
 void focus(double x,double y){State state=monitor.state;Block block=monitor.block();Model model=monitor.model(block);if(!monitor.focus||block==null||model==null)return;try{Object map=monitor.focusMaps.get(String.valueOf(model.id));if(map==null)return;monitor.focusX=normalize(x);monitor.focusY=normalize(y);monitor.enqueueFocus(Models.focus(map,x,y,model,block),new Models.Context(state,block));}catch(Exception e){problem(e.getMessage());}editor.invalidate();}
 void preciseFocus(){if(!monitor.focus)return;LinearLayout body=column();TextView xLabel=text("X "+monitor.focusX),yLabel=text("Y "+monitor.focusY);SeekBar x=new SeekBar(this),y=new SeekBar(this);x.setMax(200);y.setMax(200);x.setProgress((int)((monitor.focusX+1)*100));y.setProgress((int)((monitor.focusY+1)*100));body.addView(xLabel);body.addView(x);body.addView(yLabel);body.addView(y);SeekBar.OnSeekBarChangeListener listener=new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar view){}public void onProgressChanged(SeekBar view,int value,boolean user){xLabel.setText("X "+String.format(java.util.Locale.US,"%.2f",x.getProgress()/100.0-1));yLabel.setText("Y "+String.format(java.util.Locale.US,"%.2f",y.getProgress()/100.0-1));}public void onStopTrackingTouch(SeekBar view){focus(x.getProgress()/100.0-1,y.getProgress()/100.0-1);}};x.setContentDescription("Focus X, left to right");y.setContentDescription("Focus Y, bottom to top");x.setOnSeekBarChangeListener(listener);y.setOnSeekBarChangeListener(listener);new AlertDialog.Builder(this).setTitle("Precise Focus controls").setView(body).setNegativeButton("Close",null).setPositiveButton("Apply",(d,w)->focus(x.getProgress()/100.0-1,y.getProgress()/100.0-1)).show();}
 void restoreFocus(){Block block=monitor.block();Model model=monitor.model(block);if(block==null||model==null)return;Set<Integer> allowed=new HashSet<>();Object focus=monitor.focusMaps.get(String.valueOf(model.id));for(Object p:arr(get(focus,"params")))allowed.add(n(get(p,"id")));List<Change> changes=new ArrayList<>();for(Param p:model.params)if(!p.harness&&(focus==null||allowed.contains(p.id))&&monitor.focusStart.containsKey(p.identity()))changes.add(new Change(p,monitor.focusStart.get(p.identity()),block.value(p)));monitor.enqueueFocus(changes,new Models.Context(monitor.state,block));}
 void focusControl(String kind,Param eq,double x,double y){Block block=monitor.block();Model model=monitor.model(block);if(block==null||model==null)return;List<Change> changes=new ArrayList<>();for(Param p:model.params){if(p.harness)continue;Double v=null;if(kind.equals("cab")&&(p.key.equals("Position")||p.key.equals("Distance"))){v=p.min+clamp(p.key.equals("Position")?x:y,0,1)*(p.max-p.min);if(p.key.equals("Distance"))v=Math.floor(v*4+.5)/4;}if(kind.equals("eq")&&eq!=null){if(p==eq)v=clamp(48*y-24,p.min,p.max);if(p.key.equals(eq.key.replace("Gain","Freq"))&&p.min>0)v=clamp(20*Math.pow(1000,clamp(x,0,1)),p.min,p.max);}if(v!=null&&block.value(p)!=null)changes.add(new Change(p,clamp(v,p.min,p.max),block.value(p)));}monitor.enqueueFocus(changes,new Models.Context(monitor.state,block));}
